CREATE TYPE "SessionState" AS ENUM ('CREATED','ACTIVE','ENDED','ABANDONED','FAILED');
CREATE TYPE "ConversationMode" AS ENUM ('NATURAL','TEACHING');
CREATE TABLE practice_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,profile_id UUID NOT NULL,scenario_slug VARCHAR(40) NOT NULL,scenario_version INTEGER NOT NULL,level "CefrLevel" NOT NULL,mode "ConversationMode" NOT NULL,prompt_version VARCHAR(40) NOT NULL,state "SessionState" NOT NULL DEFAULT 'CREATED',transcript_revision INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),ended_at TIMESTAMPTZ,UNIQUE(id,account_id));
CREATE INDEX practice_sessions_account_created_idx ON practice_sessions(account_id,created_at);
CREATE TABLE conversation_turns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),session_id UUID NOT NULL,account_id UUID NOT NULL,sequence INTEGER NOT NULL,source_event_key VARCHAR(100) NOT NULL,speaker VARCHAR(16) NOT NULL,text TEXT NOT NULL,language VARCHAR(8) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(session_id,account_id) REFERENCES practice_sessions(id,account_id) ON DELETE CASCADE,UNIQUE(session_id,sequence),UNIQUE(session_id,source_event_key));
CREATE TABLE session_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),session_id UUID NOT NULL,account_id UUID NOT NULL,sequence INTEGER NOT NULL,kind VARCHAR(50) NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(session_id,account_id) REFERENCES practice_sessions(id,account_id) ON DELETE CASCADE,UNIQUE(session_id,sequence));
CREATE INDEX session_events_account_session_sequence_idx ON session_events(account_id,session_id,sequence);
